open Wmt_Entity;;
let equals (_ : graph) (a : entity) (b : entity) : comparison =
  match text a "email", text b "email" with
  | Some x, Some y ->
      decision (String.lowercase_ascii (String.trim x) =
                String.lowercase_ascii (String.trim y))
  | _ -> unknown "Both entities need email"
;;

open Wmt_Entity;;
(* Override only equals; keep the inherited contact fields. *)
let equals (_ : graph) (a : entity) (b : entity) : comparison =
  cosine ~threshold:0.92 "embedding" a b
;;

open Wmt_Entity;;
(* A policy can also inspect the supplied graph. *)
let equals (g : graph) (a : entity) (b : entity) : comparison =
  let shared = List.exists
    (fun id -> List.mem id (targets g b "worksAt"))
    (targets g a "worksAt") in
  if shared then cosine ~threshold:0.92 "embedding" a b
  else decision false
;;

open Wmt_Entity;;
let equals (_ : graph) (a : entity) (b : entity) : comparison =
  decision (text a "label" = text b "label")
;;
